/**
 * Shared types for Earshot. Nothing in here knows about YouTube, Chrome, or React —
 * it only describes transcription state so any surface (web app, extension, future
 * providers) can render it.
 */

export type TranscriptionStatus =
  | "idle"
  | "connecting"
  | "live"
  | "paused"
  | "reconnecting"
  | "error";

/** A committed (final) transcript line. Times are seconds. */
export interface TranscriptLine {
  id: string;
  text: string;
  /** Seconds since transcription started, measured in audio actually streamed. */
  start: number;
  end: number;
  /** Position in the media (e.g. video currentTime) when known; null for unseekable sources. */
  mediaStart: number | null;
  mediaEnd: number | null;
  /** Wall-clock ms when the line was committed. */
  createdAt: number;
}

/** What should be on screen as a caption right now. */
export interface CaptionState {
  /** Finalized-but-uncommitted words followed by the current interim hypothesis. */
  text: string;
  /** True when the tail of `text` is still an interim (may change) result. */
  hasInterim: boolean;
  /** Wall-clock ms of the last change; renderers use it to fade stale captions. */
  updatedAt: number;
}

export interface TranscriptState {
  status: TranscriptionStatus;
  error: string | null;
  lines: TranscriptLine[];
  caption: CaptionState;
  /** Wall-clock ms when the current session started, null when never started. */
  startedAt: number | null;
}

/** Incremental events — cheap to send across process boundaries (e.g. extension messaging). */
export type TranscriptEvent =
  | { type: "status"; status: TranscriptionStatus; error?: string | null }
  | { type: "line"; line: TranscriptLine }
  | { type: "caption"; caption: CaptionState }
  | { type: "reset"; startedAt: number | null }
  | { type: "snapshot"; state: TranscriptState };

export type CaptionFont = "sans" | "serif" | "mono";
export type CaptionPosition = "overlay" | "below";

export interface CaptionSettings {
  enabled: boolean;
  /** Font size in CSS px. */
  fontSize: number;
  fontFamily: CaptionFont;
  textColor: string;
  backgroundColor: string;
  /** 0 = no box (text shadow only), 1 = opaque. */
  backgroundOpacity: number;
  /** Web player only: draw over the video or below it. */
  position: CaptionPosition;
  /** Max visible caption lines. */
  maxLines: number;
}

export interface DeepgramStreamOptions {
  model?: string;
  language?: string;
  keyterms?: string[];
}

import type { CaptionSettings } from "./types";

export const DEFAULT_CAPTION_SETTINGS: CaptionSettings = {
  enabled: true,
  fontSize: 24,
  fontFamily: "sans",
  textColor: "#ffffff",
  backgroundColor: "#000000",
  backgroundOpacity: 0.72,
  position: "overlay",
  maxLines: 2,
};

export const CAPTION_FONT_SIZES = [16, 20, 24, 30, 38, 48] as const;

export const CAPTION_FONT_STACKS: Record<CaptionSettings["fontFamily"], string> = {
  sans: 'Inter, "Segoe UI", system-ui, -apple-system, sans-serif',
  serif: 'Georgia, "Times New Roman", serif',
  mono: '"JetBrains Mono", ui-monospace, Menlo, monospace',
};

/** Merge untrusted stored settings with defaults, clamping numeric ranges. */
export function normalizeCaptionSettings(input: unknown): CaptionSettings {
  const s = { ...DEFAULT_CAPTION_SETTINGS, ...(isObject(input) ? input : {}) } as CaptionSettings;
  return {
    enabled: Boolean(s.enabled),
    fontSize: clamp(Number(s.fontSize) || DEFAULT_CAPTION_SETTINGS.fontSize, 12, 72),
    fontFamily: ["sans", "serif", "mono"].includes(s.fontFamily) ? s.fontFamily : "sans",
    textColor: isColor(s.textColor) ? s.textColor : DEFAULT_CAPTION_SETTINGS.textColor,
    backgroundColor: isColor(s.backgroundColor) ? s.backgroundColor : DEFAULT_CAPTION_SETTINGS.backgroundColor,
    backgroundOpacity: clamp(Number(s.backgroundOpacity), 0, 1),
    position: s.position === "below" ? "below" : "overlay",
    maxLines: clamp(Math.round(Number(s.maxLines) || 2), 1, 4),
  };
}

/** `#rrggbb` + opacity → `rgba(...)`. */
export function withOpacity(hex: string, opacity: number): string {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const n = parseInt(m[1]!, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${opacity})`;
}

function clamp(n: number, min: number, max: number) {
  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : min;
}
function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null;
}
function isColor(v: unknown): v is string {
  return typeof v === "string" && /^#[0-9a-f]{6}$/i.test(v);
}

import type { TranscriptLine } from "./types";

/** 75.4 → "1:15", 3725 → "1:02:05". */
export function formatTimestamp(seconds: number): string {
  const total = Math.max(0, Math.floor(seconds));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const ss = String(s).padStart(2, "0");
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${ss}` : `${m}:${ss}`;
}

function clock(seconds: number, msSeparator: "," | "."): string {
  const totalMs = Math.max(0, Math.round(seconds * 1000));
  const h = Math.floor(totalMs / 3_600_000);
  const m = Math.floor((totalMs % 3_600_000) / 60_000);
  const s = Math.floor((totalMs % 60_000) / 1000);
  const ms = totalMs % 1000;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}${msSeparator}${String(ms).padStart(3, "0")}`;
}

export type TimeBase = "media" | "stream";

/** Media time when every line has it (seekable source), otherwise time since capture start. */
export function preferredTimeBase(lines: TranscriptLine[]): TimeBase {
  return lines.length > 0 && lines.every((l) => l.mediaStart !== null) ? "media" : "stream";
}

export function lineTimes(line: TranscriptLine, base: TimeBase): { start: number; end: number } {
  if (base === "media" && line.mediaStart !== null) {
    return { start: line.mediaStart, end: line.mediaEnd ?? line.mediaStart + (line.end - line.start) };
  }
  return { start: line.start, end: line.end };
}

export function toPlainText(lines: TranscriptLine[], opts: { timestamps?: boolean; base?: TimeBase } = {}): string {
  const base = opts.base ?? preferredTimeBase(lines);
  return lines
    .map((l) => (opts.timestamps === false ? l.text : `[${formatTimestamp(lineTimes(l, base).start)}] ${l.text}`))
    .join("\n");
}

export function toSrt(lines: TranscriptLine[], base: TimeBase = preferredTimeBase(lines)): string {
  return lines
    .map((l, i) => {
      const t = lineTimes(l, base);
      return `${i + 1}\n${clock(t.start, ",")} --> ${clock(Math.max(t.end, t.start + 0.5), ",")}\n${l.text}\n`;
    })
    .join("\n");
}

export function toVtt(lines: TranscriptLine[], base: TimeBase = preferredTimeBase(lines)): string {
  const cues = lines.map((l) => {
    const t = lineTimes(l, base);
    return `${clock(t.start, ".")} --> ${clock(Math.max(t.end, t.start + 0.5), ".")}\n${l.text}\n`;
  });
  return `WEBVTT\n\n${cues.join("\n")}`;
}

export type ExportFormat = "txt" | "srt" | "vtt";

export function exportTranscript(lines: TranscriptLine[], format: ExportFormat): { content: string; mime: string } {
  switch (format) {
    case "srt":
      return { content: toSrt(lines), mime: "application/x-subrip" };
    case "vtt":
      return { content: toVtt(lines), mime: "text/vtt" };
    default:
      return { content: toPlainText(lines), mime: "text/plain" };
  }
}

/** Browser-only helper: trigger a file download. */
export function downloadTranscript(lines: TranscriptLine[], format: ExportFormat, baseName = "transcript"): void {
  const { content, mime } = exportTranscript(lines, format);
  const url = URL.createObjectURL(new Blob([content], { type: `${mime};charset=utf-8` }));
  const a = document.createElement("a");
  a.href = url;
  a.download = `${safeFileName(baseName)}.${format}`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function safeFileName(name: string): string {
  return name.replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").slice(0, 80) || "transcript";
}

import type { CaptionState, TranscriptEvent, TranscriptLine, TranscriptState } from "./types";

/* ------------------------------------------------------------------ */
/* Pure state reducer used by every consumer (session, side panel...) */
/* ------------------------------------------------------------------ */

export const EMPTY_CAPTION: CaptionState = { text: "", hasInterim: false, updatedAt: 0 };

export function initialTranscriptState(): TranscriptState {
  return { status: "idle", error: null, lines: [], caption: EMPTY_CAPTION, startedAt: null };
}

export function reduceTranscript(state: TranscriptState, event: TranscriptEvent): TranscriptState {
  switch (event.type) {
    case "status":
      return { ...state, status: event.status, error: event.error ?? (event.status === "error" ? state.error : null) };
    case "line":
      if (state.lines.some((l) => l.id === event.line.id)) return state;
      return { ...state, lines: [...state.lines, event.line] };
    case "caption":
      return { ...state, caption: event.caption };
    case "reset":
      return { ...initialTranscriptState(), status: state.status, startedAt: event.startedAt };
    case "snapshot":
      return event.state;
  }
}

/* ------------------------------------------------------------------ */
/* Assembles Deepgram results into lines + a live caption             */
/* ------------------------------------------------------------------ */

export interface DgWord {
  word: string;
  punctuated_word?: string;
  start: number;
  end: number;
}

/** Subset of Deepgram's `Results` message we rely on. */
export interface DgResults {
  type: "Results";
  start: number;
  duration: number;
  is_final?: boolean;
  speech_final?: boolean;
  channel: { alternatives: Array<{ transcript: string; words?: DgWord[] }> };
}

interface Span {
  text: string;
  start: number;
  end: number;
}

export interface AssemblerOptions {
  /** Map stream seconds → media seconds (null if unknown). */
  mediaTimeAt?: (streamSeconds: number) => number | null;
  /** Commit long monologues at sentence boundaries once this many chars accumulate. */
  softLineLimit?: number;
  /** Always commit once this many chars accumulate. */
  hardLineLimit?: number;
  /** Max characters shown in the caption. */
  captionChars?: number;
  now?: () => number;
  idPrefix?: string;
}

/**
 * Turns a stream of Deepgram `Results` (interim + final) into committed lines and a caption.
 *
 * - `offset` is the absolute stream time at which the current WebSocket connection began,
 *   so timestamps stay monotonic across reconnects.
 * - Finals whose words end before the last committed audio are dropped, which prevents
 *   duplicated segments when audio is replayed after a reconnect or after `Finalize`.
 */
export class TranscriptAssembler {
  private pending: Span | null = null;
  private interim: Span | null = null;
  /** Absolute stream time up to which final words have been accepted. */
  private finalizedUntil = 0;
  private counter = 0;
  private readonly opts: Required<Omit<AssemblerOptions, "mediaTimeAt">> & Pick<AssemblerOptions, "mediaTimeAt">;

  constructor(
    private readonly emit: (event: TranscriptEvent) => void,
    options: AssemblerOptions = {},
  ) {
    this.opts = {
      softLineLimit: 160,
      hardLineLimit: 320,
      captionChars: 220,
      now: () => Date.now(),
      idPrefix: Math.random().toString(36).slice(2, 8),
      ...options,
    };
  }

  handleResults(msg: DgResults, offset: number): void {
    const alt = msg.channel?.alternatives?.[0];
    if (!alt) return;
    const segStart = offset + msg.start;
    const segEnd = segStart + msg.duration;

    if (!msg.is_final) {
      const text = alt.transcript.trim();
      // An interim covering only audio we already finalized is stale.
      this.interim = text && segEnd > this.finalizedUntil + 0.01 ? { text, start: segStart, end: segEnd } : null;
      this.emitCaption();
      return;
    }

    this.interim = null;
    const words = (alt.words ?? []).filter((w) => offset + w.start >= this.finalizedUntil - 0.02);
    let text: string;
    let start = segStart;
    let end = segEnd;
    if (alt.words && alt.words.length > 0) {
      text = words.map((w) => w.punctuated_word ?? w.word).join(" ").trim();
      if (words.length > 0) {
        start = offset + words[0]!.start;
        end = offset + words[words.length - 1]!.end;
      }
    } else {
      text = segEnd > this.finalizedUntil + 0.01 ? alt.transcript.trim() : "";
    }
    this.finalizedUntil = Math.max(this.finalizedUntil, segEnd);

    if (text) {
      this.pending = this.pending
        ? { text: `${this.pending.text} ${text}`, start: this.pending.start, end }
        : { text, start, end };
    }

    if (msg.speech_final) {
      this.commit();
    } else if (this.pending) {
      const len = this.pending.text.length;
      if (len >= this.opts.hardLineLimit || (len >= this.opts.softLineLimit && /[.!?]["')\]]?$/.test(this.pending.text))) {
        this.commit();
      }
    }
    this.emitCaption();
  }

  /** Deepgram `UtteranceEnd`: the speaker paused, close the current line. */
  handleUtteranceEnd(): void {
    this.commit();
    this.emitCaption();
  }

  /** Commit what we have (stop, seek, pause). Interim text is discarded because it was never confirmed. */
  flush(opts: { clearCaption?: boolean } = {}): void {
    this.commit();
    this.interim = null;
    if (opts.clearCaption) this.emit({ type: "caption", caption: { ...EMPTY_CAPTION, updatedAt: this.opts.now() } });
    else this.emitCaption();
  }

  /** Allow audio after `t` to be accepted again (new stream timeline, e.g. after reset). */
  resetTimeline(): void {
    this.pending = null;
    this.interim = null;
    this.finalizedUntil = 0;
  }

  private commit(): void {
    const p = this.pending;
    this.pending = null;
    if (!p || !p.text) return;
    const media = this.opts.mediaTimeAt;
    const mediaStart = media ? media(p.start) : null;
    const mediaEnd = media ? media(p.end) : null;
    this.lastCommitted = p.text;
    this.emit({
      type: "line",
      line: {
        id: `${this.opts.idPrefix}-${++this.counter}`,
        text: p.text,
        start: round(p.start),
        end: round(p.end),
        mediaStart: mediaStart === null ? null : round(mediaStart),
        mediaEnd: mediaEnd === null ? null : round(mediaEnd),
        createdAt: this.opts.now(),
      },
    });
  }

  private lastCommitted = "";

  private emitCaption(): void {
    const parts = [this.pending?.text, this.interim?.text].filter(Boolean) as string[];
    // Between utterances keep showing the last line until the renderer fades it.
    const text = parts.length > 0 ? parts.join(" ") : this.lastCommitted;
    this.emit({
      type: "caption",
      caption: { text: tail(text, this.opts.captionChars), hasInterim: Boolean(this.interim), updatedAt: this.opts.now() },
    });
  }
}

/** Keep the last `max` characters, cut at a word boundary. */
export function tail(text: string, max: number): string {
  if (text.length <= max) return text;
  const cut = text.slice(text.length - max);
  const space = cut.indexOf(" ");
  return space >= 0 ? cut.slice(space + 1) : cut;
}

function round(n: number) {
  return Math.round(n * 1000) / 1000;
}

/**
 * Maps "stream time" (seconds of audio sent to Deepgram) to "media time"
 * (e.g. a video's currentTime) so transcript lines can link back into the video.
 *
 * A sample is recorded each time an audio chunk is sent. Because audio is only
 * streamed while media is playing, consecutive samples advance together.
 */
export class StreamTimeMap {
  private stream: number[] = [];
  private media: Array<number | null> = [];

  record(streamSeconds: number, mediaSeconds: number | null): void {
    const last = this.stream.length - 1;
    // Thin out samples that are perfectly predictable (steady playback) to keep memory flat.
    if (last >= 1 && mediaSeconds !== null) {
      const prevMedia = this.media[last];
      const prevPrevMedia = this.media[last - 1];
      if (
        prevMedia != null &&
        prevPrevMedia != null &&
        Math.abs(mediaSeconds - prevMedia - (streamSeconds - this.stream[last]!)) < 0.05 &&
        Math.abs(prevMedia - prevPrevMedia - (this.stream[last]! - this.stream[last - 1]!)) < 0.05 &&
        streamSeconds - this.stream[last - 1]! < 5
      ) {
        this.stream[last] = streamSeconds;
        this.media[last] = mediaSeconds;
        return;
      }
    }
    this.stream.push(streamSeconds);
    this.media.push(mediaSeconds);
  }

  /** Media time for a stream time, or null if unknown. */
  mediaAt(streamSeconds: number): number | null {
    const n = this.stream.length;
    if (n === 0) return null;
    // Find the first sample at/after t (samples mark chunk *ends*).
    let lo = 0;
    let hi = n - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.stream[mid]! < streamSeconds) lo = mid + 1;
      else hi = mid;
    }
    const s = this.stream[lo]!;
    const m = this.media[lo];
    if (m === null || m === undefined) return null;
    // Media advances 1:1 with stream within a chunk run.
    const value = m - (s - streamSeconds);
    return Math.max(0, value);
  }

  clear(): void {
    this.stream = [];
    this.media = [];
  }

  get size(): number {
    return this.stream.length;
  }
}

/**
 * Tab audio → 16 kHz mono linear16 PCM chunks, using an AudioWorklet.
 *
 * The worklet source is exported as a string so each surface can load it the way its
 * Content-Security-Policy allows: the web app uses a Blob URL (`createPcmWorkletUrl`),
 * the extension ships it as a packaged file (`chrome.runtime.getURL("pcm-worklet.js")`).
 */

export const PCM_TARGET_SAMPLE_RATE = 16000;
export const PCM_WORKLET_NAME = "earshot-pcm";

export const PCM_WORKLET_SOURCE = /* js */ `
class EarshotPcmProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const o = (options && options.processorOptions) || {};
    this.ratio = sampleRate / (o.targetSampleRate || 16000);
    this.pos = 0;
    this.prev = 0;
    this.size = o.chunkSamples || 1600;
    this.chunk = new Int16Array(this.size);
    this.idx = 0;
  }
  process(inputs) {
    const input = inputs[0];
    if (!input || input.length === 0 || !input[0]) return true;
    const n = input[0].length;
    const channels = input.length;
    const mono = new Float32Array(n);
    for (let c = 0; c < channels; c++) {
      const data = input[c];
      for (let i = 0; i < n; i++) mono[i] += data[i] / channels;
    }
    // Linear-interpolation resampler; position carries across render quanta.
    while (this.pos < n - 1) {
      const i0 = Math.floor(this.pos);
      const f = this.pos - i0;
      const a = i0 < 0 ? this.prev : mono[i0];
      const b = mono[i0 + 1];
      let v = a + (b - a) * f;
      v = v < -1 ? -1 : v > 1 ? 1 : v;
      this.chunk[this.idx++] = v < 0 ? v * 0x8000 : v * 0x7fff;
      if (this.idx === this.size) {
        this.port.postMessage(this.chunk.buffer, [this.chunk.buffer]);
        this.chunk = new Int16Array(this.size);
        this.idx = 0;
      }
      this.pos += this.ratio;
    }
    this.pos -= n;
    this.prev = mono[n - 1];
    return true;
  }
}
registerProcessor("${PCM_WORKLET_NAME}", EarshotPcmProcessor);
`;

/** Blob URL for the worklet (works where CSP allows blob: scripts, e.g. the web app). */
export function createPcmWorkletUrl(): string {
  return URL.createObjectURL(new Blob([PCM_WORKLET_SOURCE], { type: "application/javascript" }));
}

export interface PcmCaptureOptions {
  stream: MediaStream;
  workletUrl: string;
  /** Route captured audio back to the speakers (needed for chrome.tabCapture, which mutes the tab). */
  preservePlayback?: boolean;
  /** Chunk length in ms. Deepgram recommends 20–250 ms. */
  chunkMs?: number;
  onChunk: (pcm: ArrayBuffer) => void;
  /** Called when the captured track ends (user clicked "Stop sharing", tab closed, ...). */
  onEnded?: () => void;
}

export interface PcmCapture {
  readonly sampleRate: number;
  stop(): Promise<void>;
}

export async function startPcmCapture(opts: PcmCaptureOptions): Promise<PcmCapture> {
  const track = opts.stream.getAudioTracks()[0];
  if (!track) throw new Error("The captured stream has no audio track. Make sure “Share tab audio” is enabled.");

  const ctx = new AudioContext({ latencyHint: "interactive" });
  try {
    await ctx.audioWorklet.addModule(opts.workletUrl);
  } catch (err) {
    await ctx.close();
    throw new Error(`Could not load the audio processor: ${(err as Error).message}`);
  }
  const source = ctx.createMediaStreamSource(opts.stream);
  const chunkSamples = Math.round((PCM_TARGET_SAMPLE_RATE * (opts.chunkMs ?? 100)) / 1000);
  const node = new AudioWorkletNode(ctx, PCM_WORKLET_NAME, {
    numberOfInputs: 1,
    numberOfOutputs: 1,
    channelCountMode: "max",
    processorOptions: { targetSampleRate: PCM_TARGET_SAMPLE_RATE, chunkSamples },
  });
  node.port.onmessage = (e: MessageEvent<ArrayBuffer>) => opts.onChunk(e.data);

  // Keep the worklet pulled by the graph without making it audible.
  const sink = ctx.createGain();
  sink.gain.value = 0;
  source.connect(node);
  node.connect(sink);
  sink.connect(ctx.destination);
  if (opts.preservePlayback) source.connect(ctx.destination);

  const onEnded = () => opts.onEnded?.();
  track.addEventListener("ended", onEnded);
  if (ctx.state === "suspended") await ctx.resume().catch(() => undefined);

  let stopped = false;
  return {
    sampleRate: PCM_TARGET_SAMPLE_RATE,
    async stop() {
      if (stopped) return;
      stopped = true;
      track.removeEventListener("ended", onEnded);
      node.port.onmessage = null;
      try {
        source.disconnect();
        node.disconnect();
        sink.disconnect();
      } catch {
        /* already disconnected */
      }
      await ctx.close().catch(() => undefined);
    },
  };
}

/** Stop every track of a stream (releases the "sharing this tab" indicator). */
export function stopStream(stream: MediaStream | null | undefined): void {
  stream?.getTracks().forEach((t) => t.stop());
}

import { PCM_TARGET_SAMPLE_RATE } from "./audio";
import type { DeepgramStreamOptions } from "./types";
import type { DgResults } from "./transcript";

export const DEEPGRAM_LISTEN_URL = "wss://api.deepgram.com/v1/listen";

/** Build the Nova-3 streaming URL for 16 kHz mono linear16 audio. */
export function buildListenUrl(opts: DeepgramStreamOptions = {}, base = DEEPGRAM_LISTEN_URL): string {
  const p = new URLSearchParams({
    model: opts.model ?? "nova-3",
    language: opts.language ?? "en",
    encoding: "linear16",
    sample_rate: String(PCM_TARGET_SAMPLE_RATE),
    channels: "1",
    interim_results: "true",
    smart_format: "true",
    endpointing: "300",
    utterance_end_ms: "1000",
    vad_events: "true",
  });
  for (const term of opts.keyterms ?? []) if (term.trim()) p.append("keyterm", term.trim());
  return `${base}?${p.toString()}`;
}

export type DeepgramServerMessage =
  | DgResults
  | { type: "UtteranceEnd"; last_word_end?: number }
  | { type: "SpeechStarted"; timestamp?: number }
  | { type: "Metadata"; request_id?: string }
  | { type: "Error" | "Warning"; description?: string; message?: string; code?: string; err_code?: string }
  | { type: string; [k: string]: unknown };

export interface DeepgramSocketHandlers {
  onOpen: () => void;
  onMessage: (msg: DeepgramServerMessage) => void;
  onClose: (info: { code: number; reason: string; wasOpen: boolean }) => void;
}

/**
 * Thin wrapper around a browser WebSocket to Deepgram's /v1/listen.
 *
 * Browsers cannot set an Authorization header on WebSockets, so the short-lived JWT
 * from POST /v1/auth/grant is passed as the `bearer` subprotocol — the same mechanism
 * the official @deepgram/sdk uses in the browser. The permanent API key never reaches
 * the client.
 */
export class DeepgramSocket {
  private ws: WebSocket;
  private opened = false;
  private closedByUs = false;

  constructor(accessToken: string, url: string, private readonly handlers: DeepgramSocketHandlers) {
    this.ws = new WebSocket(url, ["bearer", accessToken]);
    this.ws.binaryType = "arraybuffer";
    this.ws.onopen = () => {
      this.opened = true;
      handlers.onOpen();
    };
    this.ws.onmessage = (e) => {
      if (typeof e.data !== "string") return;
      try {
        handlers.onMessage(JSON.parse(e.data) as DeepgramServerMessage);
      } catch {
        /* ignore malformed frames */
      }
    };
    this.ws.onclose = (e) => handlers.onClose({ code: e.code, reason: e.reason, wasOpen: this.opened });
    this.ws.onerror = () => {
      /* onclose always follows with details */
    };
  }

  get isOpen(): boolean {
    return this.ws.readyState === WebSocket.OPEN;
  }

  get isClosedByUs(): boolean {
    return this.closedByUs;
  }

  sendAudio(pcm: ArrayBuffer): boolean {
    if (!this.isOpen) return false;
    this.ws.send(pcm);
    return true;
  }

  /** Control messages must be text frames. */
  private control(type: "KeepAlive" | "Finalize" | "CloseStream") {
    if (this.isOpen) this.ws.send(JSON.stringify({ type }));
  }

  keepAlive() {
    this.control("KeepAlive");
  }

  /** Flush the current partial as a final result without closing. */
  finalize() {
    this.control("Finalize");
  }

  /** Ask Deepgram to flush and close; resolves once closed (or after a timeout). */
  async closeGracefully(timeoutMs = 2000): Promise<void> {
    this.closedByUs = true;
    if (this.ws.readyState === WebSocket.CLOSED) return;
    if (this.ws.readyState === WebSocket.CONNECTING) {
      this.ws.close();
      return;
    }
    await new Promise<void>((resolve) => {
      const timer = setTimeout(() => {
        this.ws.close(1000);
        resolve();
      }, timeoutMs);
      this.ws.addEventListener("close", () => {
        clearTimeout(timer);
        resolve();
      });
      this.control("CloseStream");
    });
  }

  abort() {
    this.closedByUs = true;
    try {
      this.ws.close(1000);
    } catch {
      /* noop */
    }
  }
}

/** Human-readable explanation for a socket close. */
export function describeClose(code: number, reason: string, wasOpen: boolean): string {
  if (reason) return `Deepgram closed the connection: ${reason}`;
  if (!wasOpen) return "Could not connect to Deepgram. Check your network connection and API key.";
  if (code === 1008) return "Deepgram rejected the stream (policy violation).";
  if (code === 1011) return "Deepgram timed out waiting for audio.";
  return `Connection to Deepgram lost (code ${code}).`;
}

import { startPcmCapture, stopStream, PCM_TARGET_SAMPLE_RATE, type PcmCapture } from "./audio";
import { buildListenUrl, describeClose, DeepgramSocket, type DeepgramServerMessage } from "./deepgram";
import { StreamTimeMap } from "./time-map";
import { initialTranscriptState, reduceTranscript, TranscriptAssembler, type DgResults } from "./transcript";
import type { DeepgramStreamOptions, TranscriptEvent, TranscriptState, TranscriptionStatus } from "./types";

/** Throw this from `getToken` when retrying cannot help (e.g. server has no API key). */
export class FatalTranscriptionError extends Error {
  readonly fatal = true;
}

export interface TranscriptionSessionOptions {
  /** Returns a short-lived Deepgram access token (JWT from POST /v1/auth/grant). */
  getToken: () => Promise<string>;
  /** URL of the PCM AudioWorklet module (see PCM_WORKLET_SOURCE). */
  workletUrl: string;
  /** Re-route captured audio to the speakers (chrome.tabCapture mutes the tab otherwise). */
  preservePlayback?: boolean;
  /** Current media position (e.g. video currentTime) or null. Enables seekable timestamps. */
  getMediaTime?: () => number | null;
  deepgram?: DeepgramStreamOptions;
  /** Override for tests / regional endpoints. */
  listenBaseUrl?: string;
  /** Called with every transcript event (for forwarding across processes). */
  onEvent?: (event: TranscriptEvent) => void;
  maxReconnectAttempts?: number;
}

const KEEPALIVE_MS = 3000;
const MAX_BUFFER_SECONDS = 15;

interface BufferedChunk {
  pcm: ArrayBuffer;
  start: number;
}

/**
 * Owns one transcription run: audio capture → Deepgram socket → transcript assembly.
 * Provider-agnostic: give it any MediaStream with an audio track.
 */
export class TranscriptionSession {
  private state: TranscriptState = initialTranscriptState();
  private listeners = new Set<(s: TranscriptState) => void>();
  private assembler: TranscriptAssembler;
  private timeMap = new StreamTimeMap();

  private stream: MediaStream | null = null;
  private ownsStream = true;
  private capture: PcmCapture | null = null;
  private socket: DeepgramSocket | null = null;
  /** Absolute stream time of the first chunk sent on the current socket. */
  private connOffset: number | null = null;
  private streamSeconds = 0;
  private buffer: BufferedChunk[] = [];
  private gated = false;
  private running = false;
  private attempts = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private keepAliveTimer: ReturnType<typeof setInterval> | null = null;
  private lastSentAt = 0;
  private readonly onOnline = () => {
    if (this.running && !this.socket && this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
      void this.connect();
    }
  };

  constructor(private readonly opts: TranscriptionSessionOptions) {
    this.assembler = this.createAssembler();
  }

  /* ----------------------------- public API ----------------------------- */

  getState(): TranscriptState {
    return this.state;
  }

  subscribe(listener: (s: TranscriptState) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  get isRunning(): boolean {
    return this.running;
  }

  /**
   * Start transcribing `stream`. If `ownsStream` (default) the stream's tracks are stopped
   * when the session stops.
   */
  async start(stream: MediaStream, { ownsStream = true, keepTranscript = false } = {}): Promise<void> {
    if (this.running) await this.stop();
    this.running = true;
    this.stream = stream;
    this.ownsStream = ownsStream;
    this.streamSeconds = 0;
    this.buffer = [];
    this.gated = false;
    this.attempts = 0;
    this.timeMap.clear();
    this.assembler = this.createAssembler();
    if (keepTranscript) {
      this.dispatch({ type: "snapshot", state: { ...this.state, startedAt: this.state.startedAt ?? Date.now() } });
    } else {
      this.dispatch({ type: "reset", startedAt: Date.now() });
    }
    this.setStatus("connecting");

    try {
      this.capture = await startPcmCapture({
        stream,
        workletUrl: this.opts.workletUrl,
        preservePlayback: this.opts.preservePlayback,
        onChunk: (pcm) => this.onChunk(pcm),
        onEnded: () => void this.stop("Audio capture ended."),
      });
    } catch (err) {
      await this.fail((err as Error).message);
      return;
    }

    if (typeof window !== "undefined") window.addEventListener("online", this.onOnline);
    this.keepAliveTimer = setInterval(() => {
      if (this.socket?.isOpen && Date.now() - this.lastSentAt >= KEEPALIVE_MS) this.socket.keepAlive();
    }, 1000);

    await this.connect();
  }

  /**
   * Pause/resume streaming (e.g. when the video is paused). While paused no audio is
   * sent — the socket is kept alive with KeepAlive messages — so silence isn't billed.
   */
  setPaused(paused: boolean): void {
    if (!this.running || this.gated === paused) return;
    this.gated = paused;
    if (paused) {
      this.socket?.finalize();
      this.setStatus("paused");
    } else if (this.socket?.isOpen) {
      this.setStatus("live");
    }
  }

  /** The media jumped (seek). Flush pending text and clear the on-screen caption. */
  markDiscontinuity(): void {
    if (!this.running) return;
    this.socket?.finalize();
    this.assembler.flush({ clearCaption: true });
  }

  /** Stop capture and close the socket after Deepgram flushes final results. */
  async stop(errorMessage?: string): Promise<void> {
    if (!this.running) return;
    this.running = false;
    this.clearTimers();
    if (typeof window !== "undefined") window.removeEventListener("online", this.onOnline);

    const capture = this.capture;
    this.capture = null;
    await capture?.stop();

    const socket = this.socket;
    this.socket = null;
    if (socket) {
      // Keep processing messages that arrive while closing (final words).
      await socket.closeGracefully();
    }
    this.assembler.flush();
    this.buffer = [];
    if (this.ownsStream) stopStream(this.stream);
    this.stream = null;
    if (errorMessage) this.setStatus("error", errorMessage);
    else this.setStatus("idle");
  }

  /** Clear transcript lines (only while stopped). */
  clear(): void {
    if (this.running) return;
    this.dispatch({ type: "reset", startedAt: null });
  }

  /* ----------------------------- internals ----------------------------- */

  private createAssembler() {
    return new TranscriptAssembler((e) => this.dispatch(e), {
      mediaTimeAt: this.opts.getMediaTime ? (t) => this.timeMap.mediaAt(t) : undefined,
    });
  }

  private dispatch(event: TranscriptEvent) {
    this.state = reduceTranscript(this.state, event);
    this.opts.onEvent?.(event);
    for (const l of this.listeners) l(this.state);
  }

  private setStatus(status: TranscriptionStatus, error: string | null = null) {
    if (this.state.status === status && this.state.error === error) return;
    this.dispatch({ type: "status", status, error });
  }

  private onChunk(pcm: ArrayBuffer) {
    if (!this.running || this.gated) return;
    const start = this.streamSeconds;
    this.streamSeconds += pcm.byteLength / 2 / PCM_TARGET_SAMPLE_RATE;
    let media: number | null = null;
    try {
      media = this.opts.getMediaTime?.() ?? null;
    } catch {
      media = null;
    }
    this.timeMap.record(this.streamSeconds, media);

    if (this.socket?.isOpen) {
      this.send({ pcm, start });
    } else {
      this.buffer.push({ pcm, start });
      // Keep only the most recent contiguous audio while disconnected.
      while (this.buffer.length > 0 && this.streamSeconds - this.buffer[0]!.start > MAX_BUFFER_SECONDS) {
        this.buffer.shift();
      }
    }
  }

  private send(chunk: BufferedChunk) {
    if (!this.socket) return;
    if (this.connOffset === null) this.connOffset = chunk.start;
    if (this.socket.sendAudio(chunk.pcm)) this.lastSentAt = Date.now();
  }

  private async connect(): Promise<void> {
    if (!this.running) return;
    this.setStatus(this.attempts === 0 ? "connecting" : "reconnecting");

    let token: string;
    try {
      token = await this.opts.getToken();
    } catch (err) {
      if ((err as FatalTranscriptionError).fatal) return this.fail((err as Error).message);
      return this.scheduleReconnect((err as Error).message);
    }
    if (!this.running) return;

    this.connOffset = null;
    const url = buildListenUrl(this.opts.deepgram, this.opts.listenBaseUrl);
    const socket = new DeepgramSocket(token, url, {
      onOpen: () => {
        if (this.socket !== socket) return;
        this.setStatus(this.gated ? "paused" : "live");
        const pending = this.buffer;
        this.buffer = [];
        for (const chunk of pending) this.send(chunk);
      },
      onMessage: (msg) => {
        if (this.socket !== socket && !socket.isClosedByUs) return;
        this.handleMessage(msg);
      },
      onClose: ({ code, reason, wasOpen }) => {
        if (socket.isClosedByUs || this.socket !== socket) return;
        this.socket = null;
        this.assembler.flush();
        if (wasOpen) this.attempts = 0;
        this.scheduleReconnect(describeClose(code, reason, wasOpen));
      },
    });
    this.socket = socket;
  }

  private connOffsetValue() {
    return this.connOffset ?? 0;
  }

  private handleMessage(msg: DeepgramServerMessage) {
    switch (msg.type) {
      case "Results":
        this.assembler.handleResults(msg as DgResults, this.connOffsetValue());
        if (this.attempts > 0) this.attempts = 0;
        break;
      case "UtteranceEnd":
        this.assembler.handleUtteranceEnd();
        break;
      default:
        break;
    }
  }

  private scheduleReconnect(reason: string) {
    if (!this.running) return;
    this.attempts += 1;
    const max = this.opts.maxReconnectAttempts ?? 6;
    if (this.attempts > max) {
      void this.fail(`${reason} Gave up after ${max} attempts.`);
      return;
    }
    this.setStatus("reconnecting", reason);
    const delay = Math.min(500 * 2 ** (this.attempts - 1), 8000);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      void this.connect();
    }, delay);
  }

  private async fail(message: string) {
    await this.stop(message);
    if (this.state.status !== "error") this.setStatus("error", message);
  }

  private clearTimers() {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.keepAliveTimer) clearInterval(this.keepAliveTimer);
    this.reconnectTimer = null;
    this.keepAliveTimer = null;
  }
}

