import { Fragment, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { formatTimestamp, lineTimes, type TimeBase } from "../core/format";
import type { CaptionState, TranscriptLine } from "../core/types";
import { ArrowDownIcon } from "./icons";

export interface TranscriptViewProps {
  lines: TranscriptLine[];
  /** Live caption; its text is shown as the in-progress last line. */
  caption?: CaptionState;
  live?: boolean;
  query?: string;
  timeBase?: TimeBase;
  /** When provided, timestamps become buttons that seek the media. */
  onSeek?: (seconds: number) => void;
  /** Highlight the line containing this media time (e.g. current playback position). */
  activeMediaTime?: number | null;
  emptyState?: React.ReactNode;
  className?: string;
}

/** Live, searchable transcript with timestamps and smart auto-scroll. */
export function TranscriptView({
  lines,
  caption,
  live = false,
  query = "",
  timeBase = "stream",
  onSeek,
  activeMediaTime = null,
  emptyState,
  className = "",
}: TranscriptViewProps) {
  const scroller = useRef<HTMLDivElement>(null);
  const [pinned, setPinned] = useState(true);
  const q = query.trim().toLowerCase();

  const visible = useMemo(() => (q ? lines.filter((l) => l.text.toLowerCase().includes(q)) : lines), [lines, q]);
  // The in-progress text is whatever the caption shows beyond the last committed line.
  const draft = live && !q && caption?.text && caption.text !== lines[lines.length - 1]?.text ? caption.text : "";

  const activeId = useMemo(() => {
    if (activeMediaTime === null || timeBase !== "media") return null;
    let id: string | null = null;
    for (const l of lines) {
      if (l.mediaStart !== null && l.mediaStart <= activeMediaTime + 0.25) id = l.id;
    }
    return id;
  }, [lines, activeMediaTime, timeBase]);

  useLayoutEffect(() => {
    const el = scroller.current;
    if (el && pinned && !q) el.scrollTop = el.scrollHeight;
  }, [visible.length, draft, pinned, q]);

  useEffect(() => {
    const el = scroller.current;
    if (!el) return;
    const onScroll = () => setPinned(el.scrollHeight - el.scrollTop - el.clientHeight < 48);
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => el.removeEventListener("scroll", onScroll);
  }, []);

  const isEmpty = visible.length === 0 && !draft;

  return (
    <div className={`relative min-h-0 flex-1 ${className}`}>
      <div
        ref={scroller}
        className="earshot-scroll absolute inset-0 overflow-y-auto px-4 py-3"
        aria-live="polite"
        aria-relevant="additions"
        role="log"
        aria-label="Transcript"
      >
        {isEmpty ? (
          <div className="flex h-full items-center justify-center px-6 text-center text-sm text-ink-400">
            {q ? `No matches for “${query.trim()}”` : emptyState ?? "The transcript will appear here."}
          </div>
        ) : (
          <ol className="space-y-1">
            {visible.map((line) => {
              const t = lineTimes(line, timeBase);
              const seekable = Boolean(onSeek) && timeBase === "media" && line.mediaStart !== null;
              const active = line.id === activeId;
              return (
                <li
                  key={line.id}
                  className={`group grid grid-cols-[3.75rem_1fr] gap-3 rounded-lg px-2 py-1.5 transition-colors ${
                    active ? "bg-ink-800" : "hover:bg-ink-850"
                  }`}
                >
                  {seekable ? (
                    <button
                      type="button"
                      onClick={() => onSeek!(t.start)}
                      className="mt-0.5 h-fit rounded-md text-left font-mono text-xs tabular-nums text-accent hover:text-accent-strong hover:underline focus-visible:outline-2 focus-visible:outline-accent"
                      title={`Jump to ${formatTimestamp(t.start)}`}
                    >
                      {formatTimestamp(t.start)}
                    </button>
                  ) : (
                    <span className="mt-0.5 font-mono text-xs tabular-nums text-ink-500">{formatTimestamp(t.start)}</span>
                  )}
                  <p className={`text-[0.95rem] leading-relaxed ${active ? "text-ink-100" : "text-ink-200"}`}>
                    <Highlight text={line.text} query={q} />
                  </p>
                </li>
              );
            })}
            {draft && (
              <li className="grid grid-cols-[3.75rem_1fr] gap-3 px-2 py-1.5">
                <span className="mt-1.5 flex items-start">
                  <span className="h-1.5 w-1.5 animate-pulse-dot rounded-full bg-live" aria-hidden="true" />
                </span>
                <p className="text-[0.95rem] leading-relaxed text-ink-400 italic">{draft}</p>
              </li>
            )}
          </ol>
        )}
      </div>
      {!pinned && !q && !isEmpty && (
        <button
          type="button"
          onClick={() => {
            setPinned(true);
            const el = scroller.current;
            if (el) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
          }}
          className="absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-1.5 rounded-full bg-ink-700/95 px-3 py-1.5 text-xs font-medium text-ink-100 shadow-lg ring-1 ring-ink-600 backdrop-blur hover:bg-ink-600"
        >
          <ArrowDownIcon size={13} /> {live ? "Jump to live" : "Jump to latest"}
        </button>
      )}
    </div>
  );
}

function Highlight({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;
  const parts: React.ReactNode[] = [];
  const lower = text.toLowerCase();
  let i = 0;
  let k = 0;
  while (i < text.length) {
    const j = lower.indexOf(query, i);
    if (j < 0) {
      parts.push(<Fragment key={k++}>{text.slice(i)}</Fragment>);
      break;
    }
    if (j > i) parts.push(<Fragment key={k++}>{text.slice(i, j)}</Fragment>);
    parts.push(
      <mark key={k++} className="earshot-hit">
        {text.slice(j, j + query.length)}
      </mark>,
    );
    i = j + query.length;
  }
  return <>{parts}</>;
}

import { useEffect, useRef, useState } from "react";
import { downloadTranscript, toPlainText, type ExportFormat } from "../core/format";
import type { TranscriptLine } from "../core/types";
import { CheckIcon, CloseIcon, CopyIcon, DownloadIcon, SearchIcon } from "./icons";

export interface TranscriptToolbarProps {
  lines: TranscriptLine[];
  query: string;
  onQueryChange: (q: string) => void;
  /** Base file name for downloads (e.g. the video title). */
  fileName?: string;
  className?: string;
}

/** Search box + copy + download (TXT / SRT / VTT). All actions work on the in-memory transcript. */
export function TranscriptToolbar({ lines, query, onQueryChange, fileName = "transcript", className = "" }: TranscriptToolbarProps) {
  const [copied, setCopied] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const empty = lines.length === 0;
  const matches = query.trim() ? lines.filter((l) => l.text.toLowerCase().includes(query.trim().toLowerCase())).length : null;

  useEffect(() => {
    if (!menuOpen) return;
    const close = (e: MouseEvent) => {
      if (!menuRef.current?.contains(e.target as Node)) setMenuOpen(false);
    };
    const esc = (e: KeyboardEvent) => e.key === "Escape" && setMenuOpen(false);
    document.addEventListener("mousedown", close);
    document.addEventListener("keydown", esc);
    return () => {
      document.removeEventListener("mousedown", close);
      document.removeEventListener("keydown", esc);
    };
  }, [menuOpen]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(toPlainText(lines));
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      /* clipboard denied */
    }
  };

  const download = (format: ExportFormat) => {
    downloadTranscript(lines, format, fileName);
    setMenuOpen(false);
  };

  const btn =
    "inline-flex h-9 items-center justify-center gap-1.5 rounded-lg px-2.5 text-sm text-ink-300 transition-colors hover:bg-ink-800 hover:text-ink-100 disabled:pointer-events-none disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-accent";

  return (
    <div className={`flex items-center gap-1.5 ${className}`}>
      <label className="relative flex min-w-0 flex-1 items-center">
        <span className="sr-only">Search transcript</span>
        <SearchIcon size={15} className="pointer-events-none absolute left-3 text-ink-500" />
        <input
          type="search"
          value={query}
          onChange={(e) => onQueryChange(e.target.value)}
          placeholder="Search transcript"
          className="h-9 w-full min-w-0 rounded-lg bg-ink-850 pl-9 pr-16 text-sm text-ink-100 ring-1 ring-ink-700 placeholder:text-ink-500 focus:ring-accent focus:outline-none [&::-webkit-search-cancel-button]:hidden"
        />
        {query && (
          <span className="absolute right-2 flex items-center gap-1">
            <span className="text-xs tabular-nums text-ink-500">{matches}</span>
            <button type="button" onClick={() => onQueryChange("")} className="rounded p-1 text-ink-400 hover:text-ink-100" aria-label="Clear search">
              <CloseIcon size={13} />
            </button>
          </span>
        )}
      </label>
      <button type="button" className={btn} onClick={copy} disabled={empty} title="Copy transcript" aria-label="Copy transcript">
        {copied ? <CheckIcon size={16} className="text-ok" /> : <CopyIcon size={16} />}
      </button>
      <div className="relative" ref={menuRef}>
        <button
          type="button"
          className={btn}
          onClick={() => setMenuOpen((o) => !o)}
          disabled={empty}
          aria-haspopup="menu"
          aria-expanded={menuOpen}
          title="Download transcript"
          aria-label="Download transcript"
        >
          <DownloadIcon size={16} />
        </button>
        {menuOpen && (
          <div role="menu" className="absolute right-0 top-11 z-20 w-48 overflow-hidden rounded-xl bg-ink-800 p-1 shadow-2xl ring-1 ring-ink-600">
            {(
              [
                ["txt", "Text", "Timestamped .txt"],
                ["srt", "SubRip", ".srt subtitles"],
                ["vtt", "WebVTT", ".vtt subtitles"],
              ] as const
            ).map(([fmt, label, hint]) => (
              <button
                key={fmt}
                role="menuitem"
                type="button"
                onClick={() => download(fmt)}
                className="flex w-full items-baseline justify-between rounded-lg px-3 py-2 text-left text-sm text-ink-100 hover:bg-ink-700"
              >
                {label}
                <span className="text-xs text-ink-400">{hint}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

